<?php

namespace App\Http\Controllers\Api\V1;

use App\Models\{CompanyMembership, Supplier, SupplierBill, SupplierPayment, SupplierPaymentAllocation};
use App\Services\{AccountingService, AuditLogger, AuthorizationService, SupplierBillService};
use App\Support\TenantContext;
use Illuminate\Http\{JsonResponse, Request};

final class SupplierBillController
{
    public function index(Request $request, AuthorizationService $authorization): JsonResponse
    {
        $tenant=$this->tenant();$company=$request->string('company_id')->toString()?:null;$this->scope($request,$authorization,$tenant,$company);$accessible=$company?null:$authorization->accessibleCompanyIds($request->user(),$tenant,'procurement.manage');$query=SupplierBill::where('tenant_id',$tenant)->with(['supplier','company','branch','currency'])->when(is_array($accessible),fn($q)=>$q->whereIn('company_id',$accessible))->when($company,fn($q)=>$q->where('company_id',$company))->when($request->filled('supplier_id'),fn($q)=>$q->where('supplier_id',$request->string('supplier_id')))->when($request->filled('state'),fn($q)=>$q->where('state',$request->string('state')))->when($request->filled('date_from'),fn($q)=>$q->whereDate('invoice_date','>=',$request->date('date_from')))->when($request->filled('date_to'),fn($q)=>$q->whereDate('invoice_date','<=',$request->date('date_to')))->when($request->filled('search'),function($q)use($request){$term=$request->string('search')->toString();$q->where(fn($x)=>$x->where('number','ilike','%'.$term.'%')->orWhere('supplier_reference','ilike','%'.$term.'%')->orWhereHas('supplier',fn($s)=>$s->where('name','ilike','%'.$term.'%')));});$sort=in_array($request->string('sort')->toString(),['invoice_date','due_date','number','grand_total','state'],true)?$request->string('sort')->toString():'invoice_date';$direction=$request->string('direction')->toString()==='asc'?'asc':'desc';$page=$query->orderBy($sort,$direction)->paginate(min(max($request->integer('per_page',25),10),100));$posted=SupplierBill::where('tenant_id',$tenant)->where('state','posted')->when($company,fn($q)=>$q->where('company_id',$company))->get();$currencies=$posted->pluck('currency_code')->filter()->unique();$total=$currencies->count()<=1?(string)$posted->sum('grand_total'):null;$outstanding=$currencies->count()<=1?(string)$posted->sum(fn($bill)=>\App\Support\Decimal::sub((string)$bill->grand_total,(string)SupplierPaymentAllocation::where('supplier_bill_id',$bill->id)->whereHas('payment',fn($q)=>$q->where('state','posted'))->sum('amount'))):null;return response()->json(['data'=>$page,'summary'=>['total_billed'=>$total,'outstanding_payables'=>$outstanding,'currency_code'=>$currencies->count()===1?$currencies->first():null,'amounts_available'=>$currencies->count()<=1,'amounts_reason'=>$currencies->count()>1?'Multiple currencies are kept separate and are not summed without an exchange-rate policy.':null,'overdue_bills'=>$posted->filter(fn($bill)=>$bill->due_date&&$bill->due_date->isPast())->count(),'pending_approval'=>(clone $query)->whereIn('state',['submitted'])->count(),'payments_posted'=>SupplierPayment::where('tenant_id',$tenant)->where('state','posted')->when($company,fn($q)=>$q->where('company_id',$company))->count(),'supplier_credits'=>0]]);
    }
    public function store(Request $request,SupplierBillService $service,AuthorizationService $authorization,AuditLogger $audit):JsonResponse{$tenant=$this->tenant();$data=$this->validated($request);$this->scope($request,$authorization,$tenant,$data['company_id']);abort_unless(Supplier::where('tenant_id',$tenant)->whereKey($data['supplier_id'])->exists(),404);$bill=$service->createDraft($tenant,$request->user()->id,$data);$audit->record($request,'supplier_bill.created',$tenant,$bill);return response()->json(['data'=>$bill],201);}
    public function show(Request $request,SupplierBill $supplierBill,AuthorizationService $authorization):JsonResponse{$this->assertBill($request,$authorization,$supplierBill);$allocated=(string)$supplierBill->allocations()->whereHas('payment',fn($q)=>$q->where('state','posted'))->sum('amount');return response()->json(['data'=>$supplierBill->load(['supplier','company','branch','purchaseOrder.supplier','currency','lines.variant.product','lines.purchaseOrderItem','lines.goodsReceiptItem.receipt','matches','accountingEntry.lines']),'payment_summary'=>['allocated'=>$allocated,'outstanding'=>\App\Support\Decimal::sub((string)$supplierBill->grand_total,$allocated)]]);}
    public function update(Request $request,SupplierBill $supplierBill,SupplierBillService $service,AuthorizationService $authorization,AuditLogger $audit):JsonResponse{$this->assertBill($request,$authorization,$supplierBill);$bill=$service->updateDraft($supplierBill,$this->validated($request,false));$audit->record($request,'supplier_bill.updated',$this->tenant(),$bill);return response()->json(['data'=>$bill]);}
    public function match(Request $request,SupplierBill $supplierBill,SupplierBillService $service,AuthorizationService $authorization):JsonResponse{$this->assertBill($request,$authorization,$supplierBill);return response()->json(['data'=>$service->match($supplierBill)]);}
    public function submit(Request $request,SupplierBill $supplierBill,SupplierBillService $service,AuthorizationService $authorization,AuditLogger $audit):JsonResponse{$this->assertBill($request,$authorization,$supplierBill);$bill=$service->submit($supplierBill);$audit->record($request,'supplier_bill.submitted',$this->tenant(),$bill);return response()->json(['data'=>$bill]);}
    public function approve(Request $request,SupplierBill $supplierBill,SupplierBillService $service,AuthorizationService $authorization,AuditLogger $audit):JsonResponse{$this->assertBill($request,$authorization,$supplierBill);abort_unless($authorization->allows($request->user(),$this->tenant(),'accounting.post',$supplierBill->company_id,$supplierBill->branch_id),403);$bill=$service->approve($supplierBill,$request->user()->id);$audit->record($request,'supplier_bill.approved',$this->tenant(),$bill);return response()->json(['data'=>$bill]);}
    public function post(Request $request,SupplierBill $supplierBill,SupplierBillService $service,AccountingService $accounting,AuthorizationService $authorization,AuditLogger $audit):JsonResponse{$this->assertBill($request,$authorization,$supplierBill);abort_unless($authorization->allows($request->user(),$this->tenant(),'accounting.post',$supplierBill->company_id,$supplierBill->branch_id),403);$bill=$service->post($supplierBill,$this->tenant(),$request->user()->id,$accounting);$audit->record($request,'supplier_bill.posted',$this->tenant(),$bill);return response()->json(['data'=>$bill]);}
    private function validated(Request $r,bool $create=true):array{return $r->validate(['company_id'=>[$create?'required':'sometimes','uuid'],'branch_id'=>['nullable','uuid'],'supplier_id'=>[$create?'required':'sometimes','uuid'],'purchase_order_id'=>['nullable','uuid'],'currency_id'=>[$create?'required':'sometimes','uuid'],'currency_code'=>['nullable','string','size:3'],'exchange_rate'=>['nullable','regex:/^\d+(\.\d{1,12})?$/'],'supplier_reference'=>[$create?'required':'sometimes','string','max:120'],'invoice_date'=>[$create?'required':'sometimes','date'],'accounting_date'=>[$create?'required':'sometimes','date'],'due_date'=>['nullable','date'],'payment_terms'=>['nullable','string','max:80'],'description'=>['nullable','string','max:5000'],'shipping_total'=>['nullable','regex:/^\d+(\.\d{1,6})?$/'],'lines'=>[$create?'required':'sometimes','array','min:1','max:500'],'lines.*.purchase_order_item_id'=>['nullable','uuid'],'lines.*.goods_receipt_item_id'=>['nullable','uuid'],'lines.*.variant_id'=>['nullable','uuid'],'lines.*.account_id'=>['nullable','uuid'],'lines.*.description'=>['nullable','string','max:2000'],'lines.*.quantity'=>['required','regex:/^\d+(\.\d{1,6})?$/'],'lines.*.unit'=>['nullable','string','max:40'],'lines.*.unit_price'=>['required','regex:/^\d+(\.\d{1,6})?$/'],'lines.*.discount_amount'=>['nullable','regex:/^\d+(\.\d{1,6})?$/'],'lines.*.tax_amount'=>['nullable','regex:/^\d+(\.\d{1,6})?$/']]);}
    private function assertBill(Request $r,AuthorizationService $a,SupplierBill $bill):void{$tenant=$this->tenant();abort_unless((string)$bill->tenant_id===$tenant,404);$this->scope($r,$a,$tenant,$bill->company_id);}
    private function scope(Request $r,AuthorizationService $a,string $tenant,?string $company):void{if($company){abort_unless($a->allows($r->user(),$tenant,'procurement.manage',$company)||$a->allows($r->user(),$tenant,'accounting.post',$company),403);abort_unless(CompanyMembership::where('tenant_id',$tenant)->where('company_id',$company)->where('user_id',$r->user()->id)->where('status','active')->exists(),403);}}
    private function tenant():string{return (string)app(TenantContext::class)->id();}
}
